reference_pwsh:
$b = Get-Content base.json -Raw | ConvertFrom-Json -AsHashtable
$o = Get-Content override.json -Raw | ConvertFrom-Json -AsHashtable
foreach ($k in $o.Keys) {
  if ($o[$k] -is [Collections.IDictionary]) { foreach ($n in $o[$k].Keys) { $b[$k][$n] = $o[$k][$n] } }
  else { $b[$k] = $o[$k] }
}
$b | ConvertTo-Json -Depth 10 | Set-Content effective.json
